mapper.insert:
INSERT INTO know_posts (
    id, creator_id, status, type, visible, is_top, content_origin, create_time, update_time
) VALUES (
    #{id}, #{creatorId}, #{status}, #{type}, #{visible}, #{isTop},
    COALESCE(#{contentOrigin}, 'MANUAL'), #{createTime}, #{updateTime}
)

mapper.update:
UPDATE know_posts
content_url = #{contentUrl}, content_object_key = #{contentObjectKey}, content_etag = #{contentEtag}, content_size = #{contentSize}, content_sha256 = #{contentSha256}, update_time = #{updateTime}
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
title = #{title}, tag_id = #{tagId}, tags = #{tags}, img_urls = #{imgUrls}, visible = #{visible}, is_top = #{isTop}, description = #{description}, type = #{type}, update_time = #{updateTime}
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET is_top = #{isTop}, update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET visible = #{visible}, update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

UPDATE know_posts
SET status = 'deleted', update_time = NOW()
WHERE id = #{id} AND creator_id = #{creatorId}

mapper.select:
SELECT p.id, p.title, p.description, p.tags, p.img_urls AS imgUrls, u.avatar AS authorAvatar, u.nickname AS authorNickname, u.tags_json AS authorTagJson, p.publish_time AS publishTime, p.is_top AS isTop FROM know_posts p JOIN users u ON p.creator_id = u.id WHERE p.status = 'published' AND p.visible = 'public' AND p.creator_id IN
#{id}
ORDER BY p.publish_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT *
FROM know_posts
WHERE creator_id = #{creatorId}
  AND status != 'deleted'
ORDER BY create_time DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
